CREATE TYPE "Role" AS ENUM ('SUPER_ADMIN','CONTENT_MANAGER','ENQUIRY_MANAGER','AUDITOR');
CREATE TYPE "PackageKind" AS ENUM ('TOUR','HAJJ','UMRAH');
CREATE TYPE "PackageStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TYPE "EnquiryStatus" AS ENUM ('NEW','PENDING','CONTACTED','QUOTED','CONFIRMED','NOT_INTERESTED','CLOSED','SPAM');
CREATE TYPE "JobStatus" AS ENUM ('PENDING','PROCESSING','SUCCEEDED','FAILED','BLOCKED');
CREATE TABLE "AdminUser" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'ENQUIRY_MANAGER',"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AdminUser_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Package" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"title" TEXT NOT NULL,"destination" TEXT NOT NULL,"kind" "PackageKind" NOT NULL DEFAULT 'TOUR',"category" TEXT,"duration" TEXT NOT NULL,"summary" TEXT NOT NULL,"description" TEXT,"priceFrom" INTEGER,"currency" TEXT NOT NULL DEFAULT 'INR',"image" TEXT,"featured" BOOLEAN NOT NULL DEFAULT false,"sortOrder" INTEGER NOT NULL DEFAULT 0,"status" "PackageStatus" NOT NULL DEFAULT 'DRAFT',"departureDates" JSONB,"itinerary" JSONB,"inclusions" JSONB,"exclusions" JSONB,"details" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Package_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Enquiry" ("id" TEXT NOT NULL,"reference" TEXT NOT NULL,"fullName" TEXT NOT NULL,"phone" TEXT NOT NULL,"email" TEXT NOT NULL,"members" INTEGER NOT NULL,"packageId" TEXT,"packageNameSnapshot" TEXT,"preferredDate" TIMESTAMP(3) NOT NULL,"days" INTEGER NOT NULL,"instructions" TEXT,"status" "EnquiryStatus" NOT NULL DEFAULT 'NEW',"sourcePlatform" TEXT NOT NULL DEFAULT 'WEBSITE',"idempotencyKey" TEXT,"assignedAdminId" TEXT,"consentAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Enquiry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EnquiryStatusHistory" ("id" TEXT NOT NULL,"enquiryId" TEXT NOT NULL,"fromStatus" "EnquiryStatus","toStatus" "EnquiryStatus" NOT NULL,"actorId" TEXT,"actorLabel" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EnquiryStatusHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EnquiryNote" ("id" TEXT NOT NULL,"enquiryId" TEXT NOT NULL,"authorId" TEXT,"note" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EnquiryNote_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"actorId" TEXT,"actorLabel" TEXT NOT NULL,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT,"before" JSONB,"after" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IntegrationJob" ("id" TEXT NOT NULL,"enquiryId" TEXT,"type" TEXT NOT NULL,"status" "JobStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"lastError" TEXT,"nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "IntegrationJob_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SiteSettings" ("id" TEXT NOT NULL DEFAULT 'global',"companyName" TEXT NOT NULL DEFAULT 'SkyRay Holidays',"phone" TEXT,"whatsapp" TEXT,"email" TEXT,"address" TEXT,"hours" TEXT,"mapUrl" TEXT,"whatsappMessage" TEXT,"googleReviewsUrl" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SiteSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IntegrationSecret" ("id" TEXT NOT NULL,"provider" TEXT NOT NULL,"encryptedValue" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "IntegrationSecret_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AdminUser_email_key" ON "AdminUser"("email");CREATE UNIQUE INDEX "Package_slug_key" ON "Package"("slug");CREATE UNIQUE INDEX "Enquiry_reference_key" ON "Enquiry"("reference");CREATE UNIQUE INDEX "Enquiry_idempotencyKey_key" ON "Enquiry"("idempotencyKey");CREATE UNIQUE INDEX "IntegrationSecret_provider_key" ON "IntegrationSecret"("provider");
CREATE INDEX "Enquiry_status_createdAt_idx" ON "Enquiry"("status","createdAt");CREATE INDEX "Enquiry_email_idx" ON "Enquiry"("email");CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");CREATE INDEX "IntegrationJob_status_nextAttemptAt_idx" ON "IntegrationJob"("status","nextAttemptAt");
ALTER TABLE "Enquiry" ADD CONSTRAINT "Enquiry_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "Package"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Enquiry" ADD CONSTRAINT "Enquiry_assignedAdminId_fkey" FOREIGN KEY ("assignedAdminId") REFERENCES "AdminUser"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "EnquiryStatusHistory" ADD CONSTRAINT "EnquiryStatusHistory_enquiryId_fkey" FOREIGN KEY ("enquiryId") REFERENCES "Enquiry"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "EnquiryNote" ADD CONSTRAINT "EnquiryNote_enquiryId_fkey" FOREIGN KEY ("enquiryId") REFERENCES "Enquiry"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "EnquiryNote" ADD CONSTRAINT "EnquiryNote_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "AdminUser"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "AdminUser"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "IntegrationJob" ADD CONSTRAINT "IntegrationJob_enquiryId_fkey" FOREIGN KEY ("enquiryId") REFERENCES "Enquiry"("id") ON DELETE SET NULL ON UPDATE CASCADE;
